  1	public final class ArrayDisjointSet implements DisjointSet {
  2	    private static final String NEGATIVE_SIZE_MESSAGE = "size must be non-negative";
  3	
  4	    private final int[] parent;
  5	    private final int[] rank;
  6	    private final int[] componentSize;
  7	    private int componentCount;
  8	
  9	    public ArrayDisjointSet(int size) {
 10	        validateSize(size);
 11	        parent = new int[size];
 12	        rank = new int[size];
 13	        componentSize = new int[size];
 14	        componentCount = size;
 15	        initializeSingletonSets();
 16	    }
 17	
 18	    @Override
 19	    public int find(int element) {
 20	        validateIndex(element);
 21	        return findRoot(element);
 22	    }
 23	
 24	    @Override
 25	    public boolean union(int first, int second) {
 26	        int firstRoot = find(first);
 27	        int secondRoot = find(second);
 28	        if (firstRoot == secondRoot) {
 29	            return false;
 30	        }
 31	
 32	        mergeDistinctRoots(firstRoot, secondRoot);
 33	        componentCount--;
 34	        return true;
 35	    }
 36	
 37	    @Override
 38	    public boolean connected(int first, int second) {
 39	        return find(first) == find(second);
 40	    }
 41	
 42	    @Override
 43	    public int componentSize(int element) {
 44	        return componentSize[find(element)];
 45	    }
 46	
 47	    @Override
 48	    public int components() {
 49	        return componentCount;
 50	    }
 51	
 52	    @Override
 53	    public int size() {
 54	        return parent.length;
 55	    }
 56	
 57	    private void initializeSingletonSets() {
 58	        for (int i = 0; i < parent.length; i++) {
 59	            parent[i] = i;
 60	            componentSize[i] = 1;
 61	        }
 62	    }
 63	
 64	    private int findRoot(int element) {
 65	        int current = element;
 66	        int root = current;
 67	        while (parent[root] != root) {
 68	            root = parent[root];
 69	        }
 70	
 71	        while (current != root) {
 72	            int next = parent[current];
 73	            parent[current] = root;
 74	            current = next;
 75	        }
 76	
 77	        return root;
 78	    }
 79	
 80	    private void mergeDistinctRoots(int firstRoot, int secondRoot) {
 81	        if (rank[firstRoot] < rank[secondRoot]) {
 82	            attachRoot(firstRoot, secondRoot);
 83	            return;
 84	        }
 85	
 86	        if (rank[firstRoot] > rank[secondRoot]) {
 87	            attachRoot(secondRoot, firstRoot);
 88	            return;
 89	        }
 90	
 91	        attachRoot(secondRoot, firstRoot);
 92	        rank[firstRoot]++;
 93	    }
 94	
 95	    private void attachRoot(int childRoot, int parentRoot) {
 96	        parent[childRoot] = parentRoot;
 97	        componentSize[parentRoot] += componentSize[childRoot];
 98	    }
 99	
100	    private static void validateSize(int size) {
101	        if (size < 0) {
102	            throw new IllegalArgumentException(NEGATIVE_SIZE_MESSAGE);
103	        }
104	    }
105	
106	    private void validateIndex(int element) {
107	        if (element < 0 || element >= parent.length) {
108	            throw new IndexOutOfBoundsException(outOfBoundsMessage(element));
109	        }
110	    }
111	
112	    private String outOfBoundsMessage(int element) {
113	        return "index " + element + " is out of bounds for size " + parent.length;
114	    }
115	}

